      "kind": "deadlock_free",
      "id": "no-deadlock"
    }
  ],
  "preserved": [
    {
      "kind": "reachable",
      "description": "main::t1 completes",
      "goal": {
        "kind": "function_completed",
        "function": "main::t1"
