        "function": "main::t3"
      }
    },
    {
      "kind": "reachable",
      "description": "main::t1 holds [main::a, main::b] at once",
      "goal": {
        "kind": "holds_all",
        "function": "main::t1",
        "resources": [
          "main::a",
          "main::b"
        ]
      }
    },
    {
