      "goal": {
        "kind": "holds_all",
        "function": "main::t2",
        "resources": [
          "main::b",
          "main::c"
        ]
      }
    },
    {
      "kind": "reachable",
      "description": "main::t3 holds [main::c, main::a] at once",
      "goal": {
        "kind": "holds_all",
        "function": "main::t3",
        "resources": [
          "main::c",
          "main::a"
        ]
      }
    }
  ],
  "assumptions": {
    "sequential_consistency": true,
    "no_spurious_wakeups": true
  },
  "bounds": {
    "max_threads": 8,
    "max_frames_per_thread": 8,
    "max_states": 20000,
    "max_depth": 64,
    "max_boundary_events": 256
  },
  "allowed_scope": {
    "allow_lock_reorder": true
  }
}
</contract>

